<template>
  <div class="flex items-center gap-2">
    <div class="relative w-full">
      <span class="absolute start-0 inset-y-0 flex items-center justify-center px-4">
        <component :is="icon" v-if="icon" class="size-4 text-muted-foreground" />
      </span>
      <Input
        v-model="minValue"
        type="number"
        :class="cn('shadow-sm', icon && 'pl-10')"
        :placeholder="minPlaceholder"
        :min="0"
        :step="step"
      />
    </div>
    <span class="text-sm text-muted-foreground shrink-0">&ndash;</span>
    <div class="relative w-full">
      <span class="absolute start-0 inset-y-0 flex items-center justify-center px-4">
        <component :is="icon" v-if="icon" class="size-4 text-muted-foreground" />
      </span>
      <Input
        v-model="maxValue"
        type="number"
        :class="cn('shadow-sm', icon && 'pl-10')"
        class="shadow-sm"
        :placeholder="maxPlaceholder"
        :min="0"
        :step="step"
      />
    </div>
  </div>
</template>

<script setup lang="ts">
import { cn } from '@/lib/utils';

interface Props {
  value: { min: number | null; max: number | null };
  propertyNames: { min: string; max: string };
  minPlaceholder?: string;
  maxPlaceholder?: string;
  icon?: any;
  step?: string;
}

const props = withDefaults(defineProps<Props>(), {
  minPlaceholder: 'Min',
  maxPlaceholder: 'Max',
  icon: undefined,
  step: '0.01',
});

const route = useRoute();

const minValue = ref<number | null>(props.value.min);
const maxValue = ref<number | null>(props.value.max);

function parseNumber(val: number | null): number | undefined {
  if (val === null || val === undefined || isNaN(val)) return undefined;
  return val;
}

watchDebounced(
  minValue,
  async (newVal: number | null) => {
    await navigateTo({
      name: route.name,
      params: route.params,
      query: {
        ...route.query,
        page: 1,
        [props.propertyNames.min]: parseNumber(newVal),
      },
    });
  },
  { debounce: 500 }
);

watchDebounced(
  maxValue,
  async (newVal: number | null) => {
    await navigateTo({
      name: route.name,
      params: route.params,
      query: {
        ...route.query,
        page: 1,
        [props.propertyNames.max]: parseNumber(newVal),
      },
    });
  },
  { debounce: 500 }
);

watch(
  () => props.value.min,
  (newVal) => {
    if (newVal !== minValue.value) minValue.value = newVal;
  }
);

watch(
  () => props.value.max,
  (newVal) => {
    if (newVal !== maxValue.value) maxValue.value = newVal;
  }
);
</script>
